/* the current copy: the newest valid sequence (A on a tie), -1 when
 * neither is valid. Headers first, so only the winner's payload is read (it
 * is left in st_buf); *h gets its header. */
static int st_current(uint32_t obj, st_hdr_t *h)
{
    st_hdr_t a, b;
    int va = st_head(obj, 0, &a) == 0, vb = st_head(obj, 1, &b) == 0;
    if (vb && (!va || (b.seq != a.seq && b.seq - a.seq < 0x80000000u))) {
        if (st_body(obj, 1, &b) == 0) {
            *h = b;
            return 1;
        }
        vb = 0;
    }
    if (va && st_body(obj, 0, &a) == 0) {
        *h = a;
        return 0;
    }
    if (vb && st_body(obj, 1, &b) == 0) {
        *h = b;
        return 1;
    }
    return -1;
}

/* a stored kit as the voice takes it: values 0..127, the mode's fields in range (wave 0..3, filter 0..2, snap) */
static int dx_kit_ok(const dx_lane_t *k)
{
    uint32_t l, i;
    for (l = 0; l < 8u; l++) {
        if (((k[l].mode >> 2) & 3u) > DXF_HP)          /* (JIANT 0.4: bits 5..7 the pitch modulation, DRIVE) */
            return 0;
        for (i = 0; i < DXP_N; i++)
            if (k[l].a[i] > 127u || k[l].b[i] > 127u)
                return 0;
    }
    return 1;
}

/* the striped sun: a half disc on the horizon hy, gold at its top to pink and purple, cut by gaps that widen downward
 * (dim: that much into the glass, behind a graph) */
static void ne_sun(int32_t cx, int32_t hy, int32_t r, int32_t dim)
{
    int32_t y, w;
    for (y = hy - r; y < hy; y++) {
        int32_t t = (y - (hy - r)) * 1000 / r, d = hy - y;
        if (t > 420 && (y % 5) < 1 + (t - 420) * 6 / 1000)
            continue;
        for (w = r; w * w + d * d > r * r; w--)
            ;
        cv_rect(cx - w, y, 2 * w + 1, 1, ux_mix(ne_ramp(NE_SUNSET, 4, t), T_SURF, dim));
    }
}

static void ne_grid_run(int32_t x0, int32_t x1, int32_t hy, int32_t y1, uint16_t c, uint16_t under, int32_t ph)
{
    int32_t cx = (x0 + x1) / 2, i, k, n = y1 - hy;
    for (k = 0; n > 0 && k <= n; k++) {
        uint16_t f = ux_mix(c, under, 75 - 75 * k / n);
        for (i = -14; i <= 14; i++) {
            int32_t x = cx + i * 26 * k / n;
            if (x >= x0 && x < x1)
                cv_rect(x, hy + k, 1, 1, f);
        }
    }
    for (k = 1; k <= 4; k++) {
        int32_t u = (k - 1) * 1000 + ph, y = hy + n * (u / 10) * (u / 10) / 160000;
        if (y > hy && y <= y1)
            cv_rect(x0, y, x1 - x0, 1, ux_mix(c, under, 75 - 75 * u / 4000));
    }
}

