static uint32_t fm1_clk_mhz(void)
{
    uint32_t ref = ((FCLK_PLL_CON & 0x0C000000u) == 0x08000000u ? 40000u : 24000u) /
                   (((FCLK_PLL2_CON0 >> 2) & 31u) + 2u);           /* kHz */
    if ((FCLK_CLK_CON2 & 15u) != 6u || !(FCLK_CLK_CON0 & 0x100u))
        return 0;
    return (ref * fm1_clk320_mult() * 2u / 3u + 500u) / 1000u;
}

/* slot k's patch into v (unpacked); without one, as before 1.0.3: SLOT s F n that factory patch, OWN the init voice */
static void upf_patch(uint32_t k, int32_t s, uint8_t *v)
{
    uint8_t pk[FM6_PACKED];
    if (upf_get(k, pk))
        memcpy(pk, s >= 0 && s < (int32_t)FM6_NFACTORY ? FM6_FACTORY[s] : FM6_INIT, FM6_PACKED);
    fm6_unpack(pk, v);
}

static const uint8_t *ed_bk_object(uint32_t id, uint32_t *len)
{
    *len = 0;
    if (id == 0u) { *len = PROJ_SKF->size; return ED_BK_RAW; }    /* (Skiff phase 5: SKF2; phase 6: SKF3; 2.0: SKF4) */
    if (id == 1u) { *len = sizeof ed_bk_settings; return (const uint8_t *)&ed_bk_settings; }
    if (id >= 2u && id <= 5u) {                     /* ((2.0) the record's own size; one of a format of before as flash
                                                     * keeps it, for the editor's Restore to convert: proj_old) */
        const proj_fmt_t *f = proj_fmt_of(&proj_slot[id - 2u], sizeof proj_slot[0]);
#if FELUCCA_FLASH
        st_hdr_t h;
        if (proj_old(id - 2u) && st_current(OBJ_PROJECT0 + id - 2u, &h) >= 0) { *len = h.len; return st_buf; }
#endif
        if (project_used(id - 2u) && !proj_old(id - 2u)) *len = f ? f->size : sizeof proj_slot[0];   /* (the converter's
                                                                                                * SKF1: the slot) */
        return (const uint8_t *)&proj_slot[id - 2u];
    }
    if (id == 6u || id == 7u) {
        if (up_bank[id - 6u].magic == UP_BANK_MAGIC) *len = sizeof up_bank[0];
        return (const uint8_t *)&up_bank[id - 6u];
    }
    if (id == 8u)                                   /* the retired FM6 patch bank: always empty */
        return ED_BK_RAW;
    if (id == 9u) {                                 /* the user presets' FM6 patches */
        if (upf_valid(&upf)) *len = sizeof upf;
        return (const uint8_t *)&upf;
    }
    if (ED_BK_BANK(id))                             /* (Skiff) a bank chunk, read into bank.c's buffer */
        return bank_chunk(id - 16u, len);
    if (id >= 32u && id < 32u + SMP_USER_SLOTS) {
        uint32_t k = id - 32u;
        const smp_user_hdr_t *h = (const smp_user_hdr_t *)smp_user_xip(k);
        if (usr_nz[k] && h->magic == SMP_USER_MAGIC && h->data_len <= SMP_USER_SIZE - SMP_USER_DATA)
            *len = SMP_USER_DATA + h->data_len;
        return smp_user_xip(k);
    }
    return 0;
}

