/* the PERFORM layer's black key k (1..4): track k's MUTE the other way (mute_to); a second press before a staged one
 * lands takes it back. What happened, said (at once: nothing, as the GLO layer) */
static void mute_switch(uint32_t k)
{
    char b[24] = {'T', (char)('1' + k % NTRK), ' ', 0};
    k %= NTRK;
    if (mute_arm[k]) {
        str_cpy(b + 3, mute_arm[k] == 2u ? "MUTE" : "UNMUTE", sizeof b - 3u);
        mute_arm[k] = 0;
        bk.gen++;
        ui_say(b, " CANCELLED");
        return;
    }
    mute_to(k, !trk[k].p[P_MUTE]);
    if (mute_arm[k]) {
        str_cpy(b + 3, mute_arm[k] == 2u ? "MUTE" : "UNMUTE", sizeof b - 3u);
        ui_say(b, LAUNCH_AT[launch_mode()]);
    }
}

static uint32_t ota_crc16(const uint8_t *p, uint32_t n, uint32_t c)   /* poly 0x1021, init 0 */
{
    uint32_t i;
    while (n--) {
        c ^= (uint32_t)*p++ << 8;
        for (i = 0; i < 8u; i++)
            c = c & 0x8000u ? (c << 1) ^ 0x1021u : c << 1;
        c &= 0xFFFFu;
    }
    return c;
}

/* a note starts at step s (a NOTE or a REST with notes or hits; a TIE carries the one before; (2.0, #25) a note tied on
 * is the one before's) */
static int step_starts(const step_t *s)
{
    return s->time != ST_TIE && (s->hit || (s->n && step_ties(s) != (1u << s->n) - 1u));
}

