static void edit_load(uint32_t e, int32_t step)
{
    uint32_t id = snd_id();
    if (!lys.loaded)
        undo.keep = 0;
    if (e < NENGINES) {
        if (e == TSEL->eng_req % NENGINES)
            return;                                     /* its engine already: the sound stays */
        select_engine(e);
        ui.force = 1;
    } else {
        eng_list_step(step);
    }
    lys.loaded |= snd_id() != id;
}

/* step s's own values (velocity, accent, slide, RATCH, FLAM, CHANCE, condition, NUDGE; a REST) to d */
static void ed_vals(step_t *d, const step_t *s)
{
