}

/* the notes starting at i in mask m (bit k: note k; 0: every one) c long (ui.c len_get): n steps each, going on into
 * what is there ((2.0, #25) 4 notes a step, no pitch twice, not onto hits; before: empty steps only), a GATE of its
 * own a lock (the step's: the track's, none). Where one can't go on: that step's index + 1 back (it ends before it),
 * 0 = every one */
static uint32_t len_set(track_t *t, uint32_t i, uint32_t m, int32_t c)
{
    step_t w[NSTEP];
    uint32_t len = (uint32_t)t->p[P_SLEN], n = c >= LEN_STEPS ? (uint32_t)(c - LEN_STEPS) + 2u : 1u, k, j, e, p, in = 0;
    uint8_t to[4], tn[4], cnt = 0;                       /* ((2.0, #44) tails in a chain's next part) */
    ed_open(w, t, len);
    for (k = 0; k < w[i].n; k++) {
        if (step_tied(&w[i], k) || (m && !((m >> k) & 1u)))
            continue;
        for (p = w[i].note[k], e = ed_end(w, len, i, p), j = i + 1u; j <= e; j++)
            ed_del(&w[j], (uint32_t)note_at(&w[j], p));   /* (its steps after the start out: (ed_del) not w[i]'s order) */
        for (j = 1; j < n && i + j < len; j++)
            if (!ed_add(&w[i + j], p, 1)) {
                in = in ? in : i + j + 1u;
                break;
            }
        if ((e + 1u == len || i + j == len) && cnt < 4u) {   /* (at the part's end before or now: its tail, the rest */
            to[cnt] = (uint8_t)p;                            /* of it, or none) */
            tn[cnt++] = (uint8_t)(i + j == len ? n - j : 0u);
        }
    }
    for (k = 0; k < cnt; k++)                                /* (no next part, no room there: the pattern's end) */
        if (chain_tails(trk_index(t), 0, 1, &to[k], &to[k], &tn[k]) && tn[k])
            in = in ? in : len + 1u;
    ed_close(t, w, len, 0);
    if (c >= LEN_STEPS || c == motion_base_value(t, P_SGATE))
        motion_delete_event(t, i, P_SGATE);
    else
        (void)motion_set_lock(t, i, P_SGATE, (int16_t)c);   /* (full: ui_notices says so) */
    return in;
}

static const param_desc_t *page_desc(const page_t *pg, uint32_t slot, int16_t **valp)
{
    uint32_t id = pg->graph == GR_LMIX ? (slot == 1u ? P_LN0 + page_lane() : slot == 2u ? P_LPAN0 + page_lane() : 0xFFu) :
                  pg->graph != GR_LANES ? pg->id[slot] : slot == 1u ? P_LN0 + page_lane() :   /* (LANES: its LEVEL, */
                  slot == 2u ? P_LTUNE0 + page_lane() : slot == 3u ? P_LDECAY0 + page_lane() : 0xFFu;   /* (phase 9)
                                                       * TUNE, DECAY; (2.0) LANE MIX: LEVEL, PAN) */
    if (pg->graph == GR_SMIX) {                       /* (#21) SAMPLES: KNOB 1 the sample, 2..4 its LEVEL, REVERB, DELAY */
        static const param_desc_t SMX_D[4] = {PD("SAMPLE", F_INT, 1, 16, 1), PD("LEVEL", F_PCT, 0, 127, 127),
                                              PD("REVERB", F_PCT, 0, 127, 0), PD("DELAY", F_PCT, 0, 127, 0)};
        uint32_t k, z = smx_zone(&k);
        *valp = z == 0xFFu ? 0 : slot ? &usr_mix[k][slot - 1u][z] : &smx_sel;
        smx_save = 7u;                                /* (kept once the page is left: slice_store.c, a slot only when it
                                                       * changed) */
        return *valp ? &SMX_D[slot] : 0;
    }
    if (id == 0xFFu) {
        *valp = 0;
        return 0;
    }
    if (pg->scope == SC_STEP || pg->scope == SC_TRK) {
        *valp = 0;
        return 0;
    }
    if (pg->scope == SC_GLOBAL) {
        *valp = &song.g[id];
        return &GP[id];
    }
    if (pg->graph == GR_MOD) {                        /* the route shown: a fixed one's AMOUNT, a slot's SRC DST AMT */
        if (mod_ui_route < MOD_SLOT0 && slot != 3u) {
            *valp = 0;
            return 0;
        }
        id = mod_ui_route < MOD_SLOT0 ? MOD_FIXED[mod_ui_route] : id + 3u * (mod_ui_route - MOD_SLOT0);
    }
    *valp = &TSEL->p[id];
    return track_desc(TSEL, id);
}

/* every learned CC cleared (MENU > MIDI > LEARN CLEAR), the settings saved; 1 = there were */
static int ml_clear_all(void)
{
    uint32_t i, n = ml_count();
    for (i = 0; i < ML_N; i++)
        ml_put(i, 0, 0, 0);
    if (n) {
        ui.foot_sig = 0;
        settings_save();                         /* (deferred while playing) */
    }
    return n != 0u;
}

static uint32_t nm_black(uint32_t k)                   /* black key k's function: by its name (F# .. D#) */
{
    switch ((k + 5u) % 12u) {
    case 6: return NB_LEFT;
    case 8: return NB_SPACE;
    case 10: return NB_RIGHT;
    case 1: return NB_DEL;
    case 3: return NB_MODE;
    default: return NB_NONE;
    }
}

static void nm_do(uint32_t f)                          /* a black key's function */
{
    uint32_t i;
    nm_commit();
    switch (f) {
    case NB_LEFT:
        if (nm.cur)
            nm.cur--;
        break;
    case NB_RIGHT:
        if (nm.cur < nm.len)
            nm.cur++;
        break;
    case NB_SPACE:
        if (nm_insert(' '))
            nm.cur++;
        break;
    case NB_DEL:
        if (!nm.cur)
            break;
        for (i = --nm.cur; i < nm.len; i++)
            nm.s[i] = nm.s[i + 1u];
        nm.len--;
        break;
    case NB_MODE:
        nm.num ^= 1u;
        break;
    default:
        break;
    }
}

/* SEQ cursor: wraps inside the pattern length, the bank follows, a step entry ends ((1.3) the bank stays there a while,
 * follow_hold); (2.0) the selection goes; ((#44) stopped on a chain: on into its next part, back into the one before) */
static void cursor_set(int32_t c)
{
    int32_t len = TSEL->p[P_SLEN] > 0 ? TSEL->p[P_SLEN] : 1;
    if (c >= len || c < 0) {
        c = chain_cursor(c);
        len = TSEL->p[P_SLEN] > 0 ? TSEL->p[P_SLEN] : 1;
    }
    ui.cursor = (uint8_t)((c % len + len) % len);
    ui.bank = (uint8_t)(ui.cursor / 16u);
    ui.entry_open = 0;
    sel_drop();
    follow_hold();
}

/* (2.0, D 2A) OCT+ would keep something: MOMENTARY's values (LFO held), FX's macros (its layer open), PERFORM's throws */
static int keep_ready(void)
{
    uint32_t i, l = layer_open();
    for (i = 0; i < mom.n; i++)
        if (mom_fx(&mom.e[i]) ? l == LAYER_FX : mom_down())
            return 1;
    return l == LAYER_PERF && thr_out;
}

/* the header's title (BLOCKS): the page's, (phase 8) DRUM-X's sheet with the sound ("SOUND SD"), (2.0) NOTES' and FEEL's
 * with the cursor's step or the selection's range ("NOTES 5", "NOTES 5-8") */
/* (2.0, #44) NOTES, FEEL: the steps before the pattern the selected track is on in its chain (0 in none) and (*all)
 * the chain's (its LEN in none): the steps counted on through it; u 16: the grid's pages */
static uint32_t step_off(uint32_t *all, uint32_t u)
{
    uint32_t k = song.sel % NTRK, e = trk_ent(k);
    *all = ((uint32_t)TSEL->p[P_SLEN] + u - 1u) / u;
    return e < NENT ? chain_off(k, e, all, u) : 0u;
}

