static void trio_note_on(track_t *t, voice_t *v)
{
    (void)t;
    v->ph[0] = 0;
    v->ph[1] = 0x1C000000u;      /* start phases a little apart (a third apart would cancel all but
                                  * every third harmonic of equal-pitched saws until DTN drifts them) */
    v->ph[2] = 0x38000000u;
    v->s[0] = v->s[1] = 0;       /* filter */
    if (!v->s[2])
        v->s[2] = 0x2468ACE + (int32_t)v->age;   /* noise state */
    v->s[3] = 0;                 /* held noise value */
    v->s[4] = 0;                 /* the sample waiting for its step corrections */
    v->s[5] = 0;                 /* cutoff drift */
}

static void trio_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    const trio_set_t *ws = &TRIO_SETS[(uint32_t)p[P_E0] & 15u];
    uint32_t w1 = ws->w[0], w2 = ws->w[1], w3 = ws->w[2], i;
    uint32_t ring = ws->flags & TRIO_RING, sync = ws->flags & TRIO_SYNC;
    int32_t g1 = ws->g[0], g2 = ws->g[1], g3 = ws->g[2];
    uint32_t base = pitch_inc(m->pitch16);
    int32_t fine = (base >> 12) ? (int32_t)(m->inc - base) / (int32_t)(base >> 12) : 0;
    uint32_t inc1 = m->inc;
    uint32_t inc2 = trio_inc(m->pitch16, p[P_E1], p[P_E3], fine);
    uint32_t inc3 = trio_inc(m->pitch16, p[P_E2], -p[P_E3], fine);
    int32_t duty = clamp((p[P_E7] << 8) + m->shape - (64 << 8), 768, 32000);   /* Q15 */
    trio_pw_t q;
    uint32_t mode = (uint32_t)p[P_E4] & 3u;
    int32_t reso = p[P_E6], k = 8192 - reso * 7168 / 127; /* damping 2.0 .. 0.25 (Q12): no self-oscillation */
    int32_t ma = TRIO_MIX[mode][0], mb = TRIO_MIX[mode][1], mc = TRIO_MIX[mode][2];
    int32_t a1, a2, a3, cut, cur;
    tsvf_t flt;
    int32_t mix[CTL], cr[CTL + 1];                      /* blocks are CTL long (dsp.c amp_at) */
    int16_t wx[CTL];
    uint32_t ph0 = v->ph[0], ph1 = v->ph[1], ph2 = v->ph[2], ph3s = ph2;   /* state in locals: out[] may alias v->s[] */
    int32_t ic1 = v->s[0], ic2 = v->s[1], nst = v->s[2], nz = v->s[3], prev = v->s[4], drift = v->s[5];
    if (n > CTL)
        n = CTL;
    q.pw = (uint32_t)duty << 17;
    q.pdc = 2 * duty - 32768;
    q.psm = 32768 - ((duty * duty) >> 15);
    if (mode >= 2u)
        mb = -(k >> 2);                                 /* HP / notch: in - k bp (- lp) */
    /* the cutoff wanders a little, once per block (the slightly unstable filter of the chips) */
    drift += (((int32_t)(noise32(&nst) >> 22) - 512) - drift) >> 3;
    cut = clamp((p[P_E5] << 8) + m->cutoff + drift, 0, 127 << 8);
    tsvf_coef_k(&flt, cut, k);
    a1 = flt.a1;
    a2 = flt.a2;
    a3 = flt.a3;
    for (i = 0; i < n; i++) {
        mix[i] = cr[i] = 0;
        wx[i] = -1;
    }
    cr[n] = 0;
    trio_pass(w3, &ph2, inc3, g3, &q, &nz, &nst, mix, cr, 0, n);   /* first: RING reads its start phase */
    if (ring)
        trio_ring(&ph0, inc1, g1, ph3s, inc3, mix, cr, sync ? wx : 0, n);
    else
        trio_pass(w1, &ph0, inc1, g1, &q, &nz, &nst, mix, cr, sync ? wx : 0, n);
    if (sync)
        trio_sync(w2, &ph1, inc2, g2, &q, wx, mix, cr, n);
    else
        trio_pass(w2, &ph1, inc2, g2, &q, &nz, &nst, mix, cr, 0, n);
    cur = prev;
    for (i = 0; i < n; i++) {
        int32_t x = cur + cr[i], y, v1, v2, v3, a;     /* one sample late: its corrections are complete */
        cur = mix[i];
        x = soft_knee(x, 16000) >> 1;                   /* the input saturates above 16000 */
        /* SVF (dsp.c tsvf_lp, with the band-pass out); the band-pass state is compressed */
        v3 = x - ic2;
        v1 = (a1 * ic1 + a2 * v3) >> 13;
        v2 = ic2 + ((a2 * ic1 + a3 * v3) >> 13);
        ic1 = 2 * v1 - ic1;
        ic2 = clamp(2 * v2 - ic2, -150000, 150000);
        a = clamp(ic1, -49152, 49152);                  /* beyond +-49152 a quarter of the excess */
        ic1 = a + ((ic1 - a) >> 2);
        y = soft_knee((x * ma + v1 * mb + v2 * mc) >> 10, 16000);   /* linear up to half scale */
        out[i] += voice_amp(y << 1, m, i) << 1;
    }
    prev = cur + cr[n];
    v->ph[0] = ph0;
    v->ph[1] = ph1;
    v->ph[2] = ph2;
    v->s[0] = ic1;
    v->s[1] = ic2;
    v->s[2] = nst;
    v->s[3] = nz;
    v->s[4] = prev;
    v->s[5] = drift;
}

/* the decoder at sample p of zone zl (p's entry must be built) */
static void gr_seek(const gr_part_t *P, const smp_zone_t *z, uint32_t zl, uint32_t p, int32_t *pred, int32_t *idx)
{
    uint32_t e = P->zbase[zl] + (p >> GR_SEG_LOG2), q;
    *pred = P->ipred[e];
    *idx = P->iidx[e];
    for (q = p & ~(GR_SEG - 1u); q < p; q++)
        gr_dec(z, q, pred, idx);
}

static int32_t fm6_scale_level(int32_t note, const uint8_t *op)
{
    int32_t off = note - op[FP_BP] - 17;
    return off >= 0 ? fm6_scale_curve((off + 1) / 3, op[FP_RD], op[FP_RC])
                    : fm6_scale_curve(-(off - 1) / 3, op[FP_LD], op[FP_LC]);
}

static void fm6_penv_init(fm6_penv_t *e, const uint8_t *p)
{
    e->level = FM6_PENV_TAB[p[FP_PL1 + 3] % 100u] * (1 << 19);
    e->down = 1;
    fm6_penv_advance(e, p, 0);
}

static void slice_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    uint32_t pk = (uint32_t)v->s[4], i, frac = v->ph[1], rev = (pk >> 7) & 1u, stepq, rem;
    int32_t lp = 4000 + ((clamp((p[P_E7] << 8) + m->cutoff, 0, 127 << 8) * 28767) >> 15), x;
    int loop = p[P_E4] == SLC_LOOP && v->gate;
    const slc_src_t *s = v->s[6] == 2 || (pk & 7u) == SLC_SINE ? 0 : slc_get(pk & 7u);
    int16_t *rb = slc_rb(t, v);
    slc_dec_t d;
    if ((pk & 7u) == SLC_SINE && v->s[6] != 2) {        /* no material: the sine at the key's pitch + PTCH */
        smp_sine(out, n, m, p[P_E3] * 16, lp, &v->ph[0], &v->s[7]);
        return;
    }
    if (!s) {                                           /* ended, or its slot was erased */
        v->active = 0;
        return;
    }
    stepq = (pow2_q16(clamp(m->pitch16 - v->pitch_cur + p[P_E3] * 16, -1536, 576)) >> 8) * (s->rate >> 8);
    d.pos = v->ph[0];
    d.pred = v->s[0];
    d.idx = v->s[1];
    d.seg = (pk >> 3) & 15u;
    if (!v->s[6]) {                                     /* prime the interpolator */
        if (!(rev ? slc_rev(s, v, rb, 0, &x) : slc_fwd(s, v, &d, 0, &x))) {
            v->active = 0;
            return;
        }
        v->s[3] = x;
        v->s[6] = 1;
    }
    rem = rev ? v->ph[0] - v->ph[2] : v->ph[2] - d.pos;
    if (v->s[6] == 1 && !loop && rem < ((stepq * 3u * n) >> 16))
        v->s[6] = 3;                                    /* the next block fades to 0 (slice_amp) */
    for (i = 0; i < n; i++) {
        int32_t y;
        frac += stepq;
        while (frac >= 65536u) {
            frac -= 65536u;
            v->s[2] = v->s[3];
            if (!(rev ? slc_rev(s, v, rb, loop, &x) : slc_fwd(s, v, &d, loop, &x))) {
                v->s[6] = 2;                            /* the slice ended */
                v->s[3] = 0;
                break;
            }
            v->s[3] = x;
        }
        y = v->s[2] + (((v->s[3] - v->s[2]) * (int32_t)(frac >> 1)) >> 15);
        v->s[7] += mulq15(y - v->s[7], lp);             /* TONE */
        out[i] += voice_amp(v->s[7], m, i) << 1;
        if (v->s[6] == 2)
            break;
    }
    v->ph[1] = frac;
    if (!rev) {
        v->ph[0] = d.pos;
        v->s[0] = d.pred;
        v->s[1] = d.idx;
        v->s[4] = (int32_t)((pk & ~(15u << 3)) | d.seg << 3);
    }
}

